WITH with_windows AS (SELECT *, CUME_DIST() OVER (PARTITION BY event_type ORDER BY duration_sec DESC NULLS FIRST) AS duration_sec_cume_dist, AVG(duration_sec) OVER (PARTITION BY session_id ORDER BY CAST(event_time AS BIGINT) RANGE BETWEEN 2592000 PRECEDING AND CURRENT ROW) AS duration_sec_avg_30d, FIRST_VALUE(page, TRUE) OVER (PARTITION BY page, session_id ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_page FROM web_events), base AS (SELECT id, session_id, event_type, event_time, duration_sec, duration_sec_cume_dist, first_known_page, LENGTH(event_type) AS event_type_length, CASE WHEN duration_sec_cume_dist >= 0.88 THEN 'High' WHEN duration_sec_cume_dist >= 0.35 THEN 'Medium' ELSE 'Low' END AS duration_sec_cume_dist_level, COALESCE(page, 'DIRECT') AS page_filled FROM with_windows WHERE event_time >= DATE '2024-02-19'), with_dims AS (SELECT src.*, s.device FROM base src JOIN sessions s ON src.session_id = s.id), with_windows_web_events AS (SELECT id, session_id, event_type, event_time, duration_sec, duration_sec_cume_dist, first_known_page, event_type_length, duration_sec_cume_dist_level, page_filled, device, AVG(event_type_length) OVER (ORDER BY CAST(event_time AS BIGINT) RANGE BETWEEN 2592000 PRECEDING AND CURRENT ROW) AS event_type_length_avg_30d, NTILE(4) OVER (PARTITION BY session_id ORDER BY event_type_length DESC, id) AS event_type_length_bucket, MAX(duration_sec) OVER (ORDER BY CAST(event_time AS BIGINT) RANGE BETWEEN 604800 PRECEDING AND CURRENT ROW) AS duration_sec_max_7d FROM with_dims), with_dims_web_events AS (SELECT a.*, p.country, p.browser FROM with_windows_web_events a LEFT JOIN sessions p ON a.session_id = p.id), kept_keys AS (SELECT session_id FROM with_dims_web_events EXCEPT DISTINCT SELECT session_id FROM web_events WHERE event_type IN ('search', 'purchase')), reconciled AS (SELECT s.* FROM with_dims_web_events s JOIN kept_keys k ON s.session_id = k.session_id) SELECT id, event_type, event_time, duration_sec, first_known_page, device, event_type_length_bucket, duration_sec_max_7d, country FROM reconciled;
